<?php
/** Read-only view of the definition and event paths behind actual encounters. */
if(PHP_SAPI!=='cli')exit(1);
define('_GNUBOARD_',true);require dirname(__DIR__,2).'/data/dbconfig.php';
mysqli_report(MYSQLI_REPORT_OFF);
$db=@new mysqli(G5_MYSQL_HOST,G5_MYSQL_USER,G5_MYSQL_PASSWORD,G5_MYSQL_DB);
if($db->connect_errno)throw new RuntimeException('Database connection failed.');$db->set_charset('utf8mb4');
function encounter_rows($sql){global $db;$r=$db->query($sql);if(!$r)throw new RuntimeException('Encounter inspection failed.');return $r->fetch_all(MYSQLI_ASSOC);}
function encounter_monster($m){return array('id'=>$m['monster_id']??null,'name'=>$m['dg_mon_name']??null,'hp'=>$m['dg_mon_hp']??null);}
function encounter_events($events){$out=array();foreach($events as $i=>$event){$entry=array_intersect_key($event,array_flip(array('enabled','room_kind','weight','type','monster_id','text','prompt')));if(isset($event['monster']))$entry['monster']=encounter_monster($event['monster']);if(isset($event['choices']))$entry['choices']=encounter_events($event['choices']);$out[$i]=$entry;}return $out;}
$p=G5_TABLE_PREFIX;$out=array('definitions'=>array(),'sessions'=>array());
foreach(encounter_rows('SELECT dg_id,dg_title,dg_settings FROM `'.$p.'dungeon` ORDER BY dg_id') as $dg){$s=json_decode($dg['dg_settings'],true)?:array();$dg['events']=encounter_events($s['events']??array());unset($dg['dg_settings']);$dg['pool']=encounter_rows('SELECT p.*,m.name FROM `'.$p.'dungeon_monster_pool` p LEFT JOIN `'.$p.'monster_master` m ON m.monster_id=p.monster_id WHERE p.dg_id='.(int)$dg['dg_id']);$out['definitions'][]=$dg;}
foreach(encounter_rows('SELECT ds_id,dg_id,phase,version,room_id,battle_id,snapshot,started_at FROM `'.$p.'dungeon_state` WHERE snapshot IS NOT NULL AND phase IN (\'WAITING\',\'EXPLORE\',\'BATTLE\',\'BOSS_RESULT\') ORDER BY ds_id DESC LIMIT 10') as $session){$s=json_decode($session['snapshot'],true)?:array();unset($session['snapshot']);$session['pool']=array();foreach($s['monsters']??array() as $m){$entry=array_intersect_key($m,array_flip(array('monster_id','enabled','boss','weight','min_count','max_count')));if(isset($m['data']))$entry['monster']=encounter_monster($m['data']);$session['pool'][]=$entry;}$session['events']=encounter_events($s['events']??array());$rooms=encounter_rows('SELECT payload,resolved,result_text FROM `'.$p.'dungeon_maze_room` WHERE ds_id='.(int)$session['ds_id'].' AND room_id='.(int)$session['room_id']);if($rooms){$payload=json_decode($rooms[0]['payload'],true);$session['room']=array('resolved'=>$rooms[0]['resolved'],'text'=>$rooms[0]['result_text'],'monster'=>isset($payload['monster'])?encounter_monster($payload['monster']):null,'event'=>encounter_events(isset($payload['event'])?array($payload['event']):array()));}$session['battle']=array();foreach(encounter_rows('SELECT battle_id,encounter_id,monster,hp,turn_no,state FROM `'.$p.'dungeon_maze_battle` WHERE ds_id='.(int)$session['ds_id'].' AND state=\'ACTIVE\'') as $battle){$battle['monster']=encounter_monster(json_decode($battle['monster'],true)?:array());$session['battle'][]=$battle;}$out['sessions'][]=$session;}
echo json_encode($out,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),PHP_EOL;
